INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'User', 'Active Member', 'Your profile has been activated', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/active-member.png\" alt=\"Profile Activated\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0; \">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 10px auto;\">\n                                <tr>\n                                    <td style=\"background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px;\">\n                                        <span style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">✨ Profile Activated</span>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <h2 style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                Congratulations! Your Profile is <span style=\"color: #DE3B68;\">Activated</span>\n                            </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div style=\"margin: 22px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n                    <h6 style=\"margin: 0 0 10px 0; font-size: 16px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 12px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Your matrimonial profile on <strong style=\"color: #DE3B68;\">##web_friendly_name##</strong> is now verified and\n                        active. Prospective matches can discover your profile, express interest, and view your matchmaking\n                        compatibility.\n                    </p>\n                    <p style=\"margin: 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 22px;\">\n                        To unlock direct phone numbers and instant chat with shortlisted matches, upgrade to a ##web_friendly_name##\n                        Premium Membership.\n                    </p>\n                </div>\n            </td>\n        </tr>\n\n        <!-- Profile Progress Card -->\n        <tr>\n            <td align=\"center\" style=\"padding: 0 24px 20px 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #FFF1F4; background: linear-gradient(135deg, #FFF1F4 0%, #FFE4E8 100%); border: 1px solid #FBCFE8; border-radius: 20px;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 24px 20px;\">\n                            <h3 style=\"margin: 0; font-size: 17px; color: #0F172A; font-family: \'Outfit\', sans-serif; font-weight: 700;\">\n                                Your Profile Completion: <span style=\"color: #DE3B68;\">100% Ready</span>\n                            </h3>\n                            <p style=\"margin: 6px 0 16px 0; color: #64748B; font-size: 13px;\">Unlock unlimited direct contact details\n                                and matchmaking assistance</p>\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\">\n                                <tr>\n                                    <td bgcolor=\"#DE3B68\" style=\"background: #DE3B68; background: linear-gradient(135deg, #DE3B68 0%, #FF537A 100%); border-radius: 30px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"display: inline-block; color: #FFFFFF; padding: 12px 34px; border-radius: 30px; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 700; text-decoration: none;\">\n                                            Upgrade to Premium\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- 3-Step Guide -->\n        <tr>\n            <td align=\"center\" style=\"padding: 0 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 20px;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 26px 20px;\">\n                            <h4 style=\"margin: 0 0 18px 0; font-size: 16px; color: #0F172A; font-weight: 700;\">Start Your Journey in 3 Simple Steps</h4>\n\n                            <!-- Table-based 3-step row, no flex -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\">\n                                <tr>\n                                    <td align=\"center\" valign=\"top\" width=\"90\">\n                                        <img src=\"##template_image_url##/loginn-icon.png\" alt=\"Login\" width=\"48\" height=\"48\"\n                                            style=\"width: 48px; height: 48px; display: block; margin: 0 auto; object-fit: contain;\">\n                                        <p style=\"margin: 8px 0 0 0; color: #0F172A; font-family: \'Outfit\', sans-serif; font-weight: 700; font-size: 13px;\">1. Login</p>\n                                        <p style=\"margin: 2px 0 0 0; color: #64748B; font-size: 11px;\">Access Profile</p>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" width=\"24\" style=\"color: #DE3B68; font-size: 18px; font-weight: bold; padding-bottom: 28px;\">&#8594;</td>\n                                    <td align=\"center\" valign=\"top\" width=\"90\">\n                                        <img src=\"##template_image_url##/search-icon.png\" alt=\"Search\" width=\"48\" height=\"48\"\n                                            style=\"width: 48px; height: 48px; display: block; margin: 0 auto; object-fit: contain;\">\n                                        <p style=\"margin: 8px 0 0 0; color: #0F172A; font-family: \'Outfit\', sans-serif; font-weight: 700; font-size: 13px;\">2. Search</p>\n                                        <p style=\"margin: 2px 0 0 0; color: #64748B; font-size: 11px;\">Filter Matches</p>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" width=\"24\" style=\"color: #DE3B68; font-size: 18px; font-weight: bold; padding-bottom: 28px;\">&#8594;</td>\n                                    <td align=\"center\" valign=\"top\" width=\"90\">\n                                        <img src=\"##template_image_url##/match-icon.png\" alt=\"Match\" width=\"48\" height=\"48\"\n                                            style=\"width: 48px; height: 48px; display: block; margin: 0 auto; object-fit: contain;\">\n                                        <p style=\"margin: 8px 0 0 0; color: #0F172A; font-family: \'Outfit\', sans-serif; font-weight: 700; font-size: 13px;\">3. Match</p>\n                                        <p style=\"margin: 2px 0 0 0; color: #64748B; font-size: 11px;\">Connect Forever</p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-top: 22px;\">\n                                <tr>\n                                    <td bgcolor=\"#DE3B68\" style=\"background: #DE3B68; border-radius: 12px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"display: inline-block; color: #FFFFFF; padding: 12px 34px; border-radius: 12px; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 700; text-decoration: none;\">\n                                            Find Your Match Now\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\" style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\" height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\" style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\" alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\" style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\" height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\" style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\" alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\" style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\" height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\" style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\" alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\" style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\" height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\" style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\" alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                ##footer_copywright_text## &#8226; <a href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(2, 'User', 'Email Confirmation', 'Verify Your Email Address on ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/email-verification.png\"\n                                                            alt=\"Verify Your Email Address\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 10px auto;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px;\">\n                                                     