                                              </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2026-08-31 15:06:47', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(3, 'User', 'Registration', 'Thank You for Registering with ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/registration.png\"\n                                                            alt=\"Welcome to ##web_friendly_name##\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 10px auto;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px;\">\n                                                        <span\n                                                            style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🎉\n                                                            WELCOME TO\n                                                            ##web_friendly_name##</span>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <h2\n                                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                                <span\n                                                    style=\"color: #DE3B68;\">Successfully</span>\n                                                Registered!\n                                            </h2>\n                                        </td>\n                                    </tr>\n                                </table>\n\n                                <div\n                                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                                    <h6\n                                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                                        Dear <span\n                                            style=\"color: #DE3B68;\">##user_name##</span>,\n                                    </h6>\n                                    <p\n                                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        Welcome to <strong\n                                            style=\"color: #0F172A;\">##web_friendly_name##</strong>!\n                                        Your profile has been registered\n                                        successfully. You have taken the first\n                                        exciting step toward finding your life\n                                        partner. Log in now to\n                                        set your partner preferences and browse\n                                        compatible profiles.\n                                    </p>\n                                    <div\n                                        style=\"text-align: center; margin: 22px 0 10px 0;\">\n                                        <a href=\"##login_url##\"\n                                            style=\"display: inline-block; background: linear-gradient(135deg, #DE3B68 0%, #FF537A 100%); color: #ffffff; padding: 13px 38px; border-radius: 30px; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 700; text-decoration: none; box-shadow: 0 6px 18px rgba(222, 59, 104, 0.35);\">\n                                            Log In to ##web_friendly_name##\n                                        </a>\n                                    </div>\n                                </div>\n                            </td>\n                        </tr>\n\n                        <!-- App Download Banner -->\n                        <tr>\n                            <td align=\"center\"\n                                style=\"padding: 22px 24px 0 24px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                                    <tr>\n                                        <td style=\"padding: 24px 26px;\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" width=\"100%\">\n                                                <tr>\n                                                    <td width=\"52%\"\n                                                        valign=\"middle\">\n                                                        <h2\n                                                            style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                                            Happiness is just an\n                                                            app away!\n                                                        </h2>\n                                                        <p\n                                                            style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                                            Download Our App,\n                                                            Register For Free\n                                                            &amp; Connect With\n                                                            Verified Matches\n                                                            Anywhere\n                                                        </p>\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\"\n                                                            style=\"margin-top: 14px;\">\n                                                            <tr>\n                                                                <td\n                                                                    style=\"padding-right: 6px;\">\n                                                                    <a\n                                                                        href=\"##ios_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/app-store.png\"\n                                                                            alt=\"App Store\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                                <td>\n                                                                    <a\n                                                                        href=\"##play_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/play-btn.png\"\n                                                                            alt=\"Google Play\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                    <td width=\"48%\"\n                                                        align=\"center\"\n                                                        valign=\"middle\">\n                                                        <img\n                                                            src=\"##template_image_url##/app-mokup.png\"\n                                                            alt=\"App Mockup\"\n                                                            width=\"220\"\n                                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Footer -->\n                        <tr>\n                            <td style=\"padding-top: 28px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #0F172A; border-radius: 0