                                         <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##instagram_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//ins.png\"\n                                                                            alt=\"Instagram\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##facebook_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//fb-2.png\"\n                                                                            alt=\"Facebook\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##youtube_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//youtube.png\"\n                                                                            alt=\"Youtube\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(4, 'User', 'Membership Activated', 'Membership Activated — Your Plan Is Now Active on ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/payment-received.png\"\n                                                            alt=\"Payment Successful - Membership Activated\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <div\n                                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                                <span\n                                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">✨\n                                                    PAYMENT SUCCESSFUL</span>\n                                            </div>\n                                            <h2\n                                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                                <span\n                                                    style=\"color: #DE3B68;\">Membership\n                                                    Plan </span>Activated\n                                            </h2>\n                                        </td>\n                                    </tr>\n                                </table>\n\n                                <div\n                                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                                    <h6\n                                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                                        Dear <span\n                                            style=\"color: #DE3B68;\">##user_name##</span>,\n                                    </h6>\n                                    <p\n                                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        Thank you for your purchase! Your\n                                        payment has been\n                                        received successfully, and your\n                                        membership plan on\n                                        <strong\n                                            style=\"color: #0F172A;\">##web_friendly_name##</strong>\n                                        is now active.\n                                    </p>\n\n                                    <p\n                                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        You can now enjoy all the benefits\n                                        included with your\n                                        membership plan, including enhanced\n                                        features and\n                                        additional opportunities to connect with\n                                        potential life\n                                        partners.\n                                    </p>\n\n                                    <p\n                                        style=\"margin: 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        We’re excited to have you with us. Thank\n                                        you for\n                                        choosing\n                                        <strong\n                                            style=\"color: #0F172A;\">##web_friendly_name##</strong>\n                                        to help you find your perfect match.\n                                    </p>\n                                </div>\n                            </td>\n                        </tr>\n\n                        <!-- App Download Banner -->\n                        <tr>\n                            <td align=\"center\"\n                                style=\"padding: 22px 24px 0 24px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                                    <tr>\n                                        <td style=\"padding: 24px 26px;\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" width=\"100%\">\n                                                <tr>\n                                                    <td width=\"52%\"\n                                                        valign=\"middle\">\n                                                        <h2\n                                                            style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                                            Happiness is just an\n                                                            app away!\n                                                        </h2>\n                                                        <p\n                                                            style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                                            Download Our App,\n                                                            Register For Free\n                                                            &amp; Connect With\n                                                            Verified Matches\n                                                            Anywhere\n                                                        </p>\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\"\n                                                            style=\"margin-top: 14px;\">\n                                                            <tr>\n                                                                <td\n                                                                    style=\"padding-right: 6px;\">\n                                                                    <a\n                                                                        href=\"##ios_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/app-store.png\"\n                                                                            alt=\"App Store\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                                <td>\n                                                                    <a\n                                                                        href=\"##play_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/play-btn.png\"\n                                                                            alt=\"Google Play\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                    <td width=\"48%\"\n                                                        align=\"center\"\n                                                        valign=\"middle\">\n                                                        <img\n                                                            src=\"##template_image_url##/app-mokup.png\"\n                                                            alt=\"App Mockup\"\n                                                            width=\"220\"\n                                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Footer -->\n                        <tr>\n                            <td style=\"padding-top: 28px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding: 32px 24px 24px 24px;\">\n\n                                            <!-- Brand -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\">\n                                                        <a href=\"##web_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"text-decoration: none; display: inline-block;\">\n                                                            <img\n                                                                src=\"##logo_url##\"\n                                                                alt=\"##web_friendly_name##\"\n                                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Trust Badges -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                width=\"100%\"\n                                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        100% Verified Profiles\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Privacy Protected\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Best Matches\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Quick Action Links -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##matches_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse\n                                                            Matches</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##membership_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership\n                                                            Plans</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##succes_story_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success\n                                                            Stories</a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Support Box -->\n                                            <p\n                                                style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                                Need assistance? Our dedicated\n                                                relationship advisors are\n                                                available 24/7.<br>\n                                                Write to us at <a\n                                                    href=\"mailto:##contact_email##\"\n                                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a>\n                                                or call\n                                                <span\n                                                    style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                                            </p>\n\n                                            <!-- Social Media Hub -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##instagram_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//ins.png\"\n                                                                            alt=\"Instagram\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##facebook_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//fb-2.png\"\n                                                                            alt=\"Facebook\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##youtube_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//youtube.png\"\n                                                                            alt=\"Youtube\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(5, 'User', 'Payment Receipt', 'Payment Receipt — Thank You for Your Payment | ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/payment-received.png\"\n                                                            alt=\"Thank You For Your Payment\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <div\n                                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                                <span\n                                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🧾\n                                                    PAYMENT RECEIPT</span>\n                                            </div>\n                                            <h2\n                                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                                <span\n                                                    style=\"color: #DE3B68;\">Thanks\n                                                    For Your </span>Payment!\n                                            </h2>\n                                        </td>\n                                    </tr>\n                                </table>\n\n                                <div\n                                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                                    <h6\n                                        style=\"margin: 0 0 12px 0; font-size: 15px; color: #0F172A; font-weight: 700; text-align: center;\">\n                                        We have attached your official\n                                        transaction receipt below\n                                    </h6>\n                                    <div\n                                        style=\"background: #ffffff; border: 1px solid #F1F5F9; border-radius: 14px; padding: 14px 20px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px;\">\n                                        <div style=\"text-align: left;\">\n                                            <span\n                                                style=\"font-size: 11px; color: #64748B; font-weight: 600; text-transform: uppercase; display: block;\">Invoice\n                                                ID</span>\n                                            <span\n                                                style=\"font-size: 15px; color: #0F172A; font-weight: 700;\">##invoice_id##</span>\n                                        </div>\n                                        <div style=\"text-align: right;\">\n                                            <span\n                                                style=\"font-size: 11px; color: #64748B; font-weight: 600; text-transform: uppercase; display: block;\">Amount\n                                                Paid</span>\n                                            <span\n                                                style=\"font-size: 16px; color: #DE3B68; font-weight: 800;\">##invoice_amount##\n                                                /-</span>\n                                        </div>\n                                    </div>\n                                    <div\n                                        style=\"text-align: center; margin: 10px 0;\">\n                                        <a href=\"##invoice_download_url##\"\n                                            style=\"display: inline-block; background: linear-gradient(135deg, #DE3B68 0%, #FF537A 100%); color: #ffffff; padding: 13px 38px; border-radius: 30px; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 700; text-decoration: none; box-shadow: 0 6px 18px rgba(222, 59, 104, 0.35);\">\n                                            Download Invoice (PDF)\n                                        </a>\n                                    </div>\n                                </div>\n                            </td>\n                        </tr>\n\n                        <!-- App Download Banner -->\n                        <tr>\n                            <td align=\"center\"\n                                style=\"padding: 22px 24px 0 24px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                                    <tr>\n                                        <td style=\"padding: 24px 26px;\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" width=\"100%\">\n                                                <tr>\n                                                    <td width=\"52%\"\n                                                        valign=\"middle\">\n                                                        <h2\n                                                            style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                                            Happiness is just an\n                                                            app away!\n                                                        </h2>\n                                                        <p\n                                                            style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                                            Download Our App,\n                                                            Register For Free\n                                                            &amp; Connect With\n                                                            Verified Matches\n                                                            Anywhere\n                                                        </p>\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\"\n                                                            style=\"margin-top: 14px;\">\n                                                            <tr>\n                                                                <td\n                                                                    style=\"padding-right: 6px;\">\n                                                                    <a\n                                                                        href=\"##ios_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/app-store.png\"\n                                                                            alt=\"App Store\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                                <td>\n                                                                    <a\n                                                                        href=\"##play_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/play-btn.png\"\n                                                                            alt=\"Google Play\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                    <td width=\"48%\"\n                                                        align=\"center\"\n                                                        valign=\"middle\">\n                                                        <img\n                                                            src=\"##template_image_url##/app-mokup.png\"\n                                                            alt=\"App Mockup\"\n                                                            width=\"220\"\n                                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Footer -->\n                        <tr>\n                            <td style=\"padding-top: 28px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding: 32px 24px 24px 24px;\">\n\n                                            <!-- Brand -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\">\n                                                        <a href=\"##web_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"text-decoration: none; display: inline-block;\">\n                                                            <img\n                                                                src=\"##logo_url##\"\n                                                                alt=\"##web_friendly_name##\"\n                                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Trust Badges -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                width=\"100%\"\n                                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        100% Verified Profiles\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Privacy Protected\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Best Matches\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Quick Action Links -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##matches_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse\n                                                            Matches</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##membership_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership\n                                                            Plans</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##succes_story_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success\n                                                            Stories</a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Support Box -->\n                                            <p\n                                                style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                                Need assistance? Our dedicated\n                                                relationship advisors are\n                                                available 24/7.<br>\n                                                Write to us at <a\n                                                    href=\"mailto:##contact_email##\"\n                                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a>\n                                                or call\n                                                <span\n                                                    style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                                            </p>\n\n                                            <!-- Social Media Hub -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##instagram_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//ins.png\"\n                                                                            alt=\"Instagram\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##facebook_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//fb-2.png\"\n                                                                            alt=\"Facebook\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##youtube_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//youtube.png\"\n                                                                            alt=\"Youtube\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(6, 'User', 'Change Password', 'Your profile password has been changed.', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/change-password.png\" alt=\"Password Changed Successfully\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                            style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                            <span\n                                style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🔑\n                                SECURITY CONFIRMATION</span>\n                        </div>\n                        <h2\n                            style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                            Password <span style=\"color: #DE3B68;\">Successfully Changed</span>\n                        </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                    This is a confirmation that the password for your <strong style=\"color: #0F172A;\">##web_friendly_name##</strong> account was recently changed successfully.\n                </p>\n\n                <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                    If you made this change, no further action is required. Your new password can now be used to sign in to your account.\n                </p>\n\n                <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                    If you did not change your password, please contact our support team immediately to secure your account.\n                </p>\n\n                <p style=\"margin: 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                    Thank you for choosing <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>.\n                </p>\n\n                </div>\n            </td>\n        </tr>\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(7, 'User', 'Interest Received', 'Expressed interest received from sender in your ##web_friendly_name## profile', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/express-interest.png\" alt=\"Express Interest Received\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                            style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                            <span\n                                style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">💌 NEW CONNECTION</span>\n                        </div>\n                        <h2\n                            style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                            <span style=\"color: #DE3B68;\">Express Interest </span>Received!\n                        </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\"> Great news! You have received a new <strong style=\"color: #0F172A;\">Express Interest</strong> from another member on <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>. </p> <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\"> Log in to your account to view the member\'s profile, respond to their interest, and take the next step toward finding your perfect match. </p> <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\"> To increase your chances of receiving more responses, we recommend completing your profile to <strong style=\"color: #DE3B68;\">100%</strong>. Members with complete profiles are more likely to attract genuine interest and build meaningful connections. </p> <p style=\"margin: 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\"> Thank you for choosing <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>. We are delighted to be a part of your journey toward finding your perfect life partner. </p>\n                </div>\n            </td>\n        </tr>\n\n        <!-- Html Templates -->\n        ##member_data_html##\n        <!-- Html Templates -->\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(8, 'User', 'Interest Reminder', 'Reminder: You Have an Interest Waiting for You on ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/express-interest.png\" alt=\"Express Interest Received\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                            style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                            <span\n                                style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">💌 INTEREST REMINDER</span>\n                        </div>\n                        <h2\n                            style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                            <span style=\"color: #DE3B68;\">Don\'t Miss </span>Your New Interest!\n                        </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n\n                    <p\n                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Just a friendly reminder that you have an <strong style=\"color: #DE3B68;\">Express Interest</strong>\n                        waiting for you on <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>.\n                    </p>\n\n                    <p\n                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Take a moment to log in, view the member\'s profile, and respond to their interest.\n                        You never know where a simple connection might lead.\n                    </p>\n\n                    <p\n                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Keep your profile updated and complete to <strong style=\"color: #DE3B68;\">100%</strong>\n                        to make a great impression and increase your chances of meaningful connections.\n                    </p>\n\n                    <p\n                        style=\"margin: 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Thank you for choosing <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>.\n                        We\'re happy to be part of your journey toward finding your perfect life partner.\n                    </p>\n                </div>\n            </td>\n        </tr>\n\n        <!-- Html Templates -->\n        ##member_data_html##\n        <!-- Html Templates -->\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(9, 'User', 'Bulk Email', '##email_subject##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/match-send-mail.png\"\n                                                            alt=\"Express Interest Received\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                            <h2\n                                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                                ##email_subject##\n                                            </h2>\n                                        </td>\n                                    </tr>\n                                </table>\n\n                                <div\n                                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n                                    <p\n                                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        ##email_content##\n                                    </p>\n                                </div>\n                            </td>\n                        </tr>\n\n                        <!-- Footer -->\n                        <tr>\n                            <td style=\"padding-top: 28px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding: 32px 24px 24px 24px;\">\n\n                                            <!-- Brand -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\">\n                                                        <a href=\"##web_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"text-decoration: none; display: inline-block;\">\n                                                            <img\n                                                                src=\"##logo_url##\"\n                                                                alt=\"##web_friendly_name##\"\n                                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Trust Badges -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                width=\"100%\"\n                                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        100% Verified Profiles\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Privacy Protected\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Best Matches\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Quick Action Links -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##matches_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse\n                                                            Matches</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##membership_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership\n                                                            Plans</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##succes_story_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success\n                                                            Stories</a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Support Box -->\n                                            <p\n                                                style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                                Need assistance? Our dedicated\n                                                relationship advisors are\n                                                available 24/7.<br>\n                                                Write to us at <a\n                                                    href=\"mailto:##contact_email##\"\n                                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a>\n                                                or call\n                                                <span\n                                                    style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                                            </p>\n\n                                            <!-- Social Media Hub -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##instagram_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//ins.png\"\n                                                                            alt=\"Instagram\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##facebook_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//fb-2.png\"\n                                                                            alt=\"Facebook\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##youtube_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//youtube.png\"\n                                                                            alt=\"Youtube\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(10, 'User', 'Match Send Mail', 'You are receiving this mail as a New Match found on ##web_friendly_name##.', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/match-send-mail.png\" alt=\"Your Matchmaking Profile\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                <span\n                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">💍 NEW MATCHES FOUND</span>\n                            </div>\n                        <h2\n                            style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                            <span style=\"color: #DE3B68;\">Your Matchmaking </span>Profiles!\n                        </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        There are some match making profile for you. Please Log on to ##web_friendly_name## now to find your perfect match. Thank you for choosing us to reach you better.\n                    </p>\n                </div>\n            </td>\n        </tr>\n\n        <!-- Html Templates -->\n        ##member_data_html##\n        <!-- Html Templates -->\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(11, 'User', 'Auto Match Send', 'Your matches at ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n\n        <title>##email_subject##</title>\n        <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n        <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n        <link\n            href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\"\n            rel=\"stylesheet\">\n        <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n            width=\"100%\" align=\"center\">\n            <tr>\n                <td align=\"center\">\n\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n                        border=\"0\" width=\"600\"\n                        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n                        <!-- Header Section -->\n                        <tr>\n                            <td\n                                style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                                <table cellpadding=\"0\" cellspacing=\"0\"\n                                    border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"left\" valign=\"middle\">\n                                            <a href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration: none; display: inline-block;\">\n                                                <img alt=\"##web_friendly_name##\"\n                                                    src=\"##logo_url##\"\n                                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                                            </a>\n                                        </td>\n                                        <td align=\"right\" valign=\"middle\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 6px 14px;\"\n                                                        valign=\"middle\">\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n                                                            <tr>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_number##\n                                                                </td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                                    ##contact_email##\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Middle Hero Section -->\n                        <tr>\n                            <td style=\"padding: 10px 26px 18px 26px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding-top: 10px;\">\n                                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin: 0 auto 12px auto;\">\n                                                <tr>\n                                                    <td width=\"110\" height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                                        <img\n                                                            src=\"##template_image_url##/auto-match-send.png\"\n                                                            alt=\"Auto Match\"\n                                                            width=\"65\"\n                                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <div\n                                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                                <span\n                                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🎯\n                                                    SMART MATCHMAKER</span>\n                                            </div>\n                                            <h2\n                                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                                <span\n                                                    style=\"color: #DE3B68;\">Auto\n                                                    Match </span>Highlights For\n                                                You\n                                            </h2>\n                                        </td>\n                                    </tr>\n                                </table>\n\n                                <div\n                                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n\n                                    <h6\n                                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                                        Dear <span\n                                            style=\"color: #DE3B68;\">##user_name##</span>,\n                                    </h6>\n                                    <p\n                                        style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                                        There are some match making profile for\n                                        you. Please Log on to\n                                        ##web_friendly_name## now to find your\n                                        perfect match. Thank you for choosing us\n                                        to reach you better.\n                                    </p>\n                                </div>\n                            </td>\n                        </tr>\n\n                        <!-- Html Templates -->\n                        ##member_data_html##\n                        <!-- Html Templates -->\n\n                        <!-- App Download Banner -->\n                        <tr>\n                            <td align=\"center\"\n                                style=\"padding: 22px 24px 0 24px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                                    <tr>\n                                        <td style=\"padding: 24px 26px;\">\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" width=\"100%\">\n                                                <tr>\n                                                    <td width=\"52%\"\n                                                        valign=\"middle\">\n                                                        <h2\n                                                            style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                                            Happiness is just an\n                                                            app away!\n                                                        </h2>\n                                                        <p\n                                                            style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                                            Download Our App,\n                                                            Register For Free\n                                                            &amp; Connect With\n                                                            Verified Matches\n                                                            Anywhere\n                                                        </p>\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\"\n                                                            style=\"margin-top: 14px;\">\n                                                            <tr>\n                                                                <td\n                                                                    style=\"padding-right: 6px;\">\n                                                                    <a\n                                                                        href=\"##ios_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/app-store.png\"\n                                                                            alt=\"App Store\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                                <td>\n                                                                    <a\n                                                                        href=\"##play_store_url##\"\n                                                                        style=\"display: inline-block;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##/play-btn.png\"\n                                                                            alt=\"Google Play\"\n                                                                            width=\"84\"\n                                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                                    </a>\n                                                                </td>\n                                                            </tr>\n                                                        </table>\n                                                    </td>\n                                                    <td width=\"48%\"\n                                                        align=\"center\"\n                                                        valign=\"middle\">\n                                                        <img\n                                                            src=\"##template_image_url##/app-mokup.png\"\n                                                            alt=\"App Mockup\"\n                                                            width=\"220\"\n                                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                        <!-- Footer -->\n                        <tr>\n                            <td style=\"padding-top: 28px;\">\n                                <table role=\"presentation\" cellpadding=\"0\"\n                                    cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                                    <tr>\n                                        <td align=\"center\"\n                                            style=\"padding: 32px 24px 24px 24px;\">\n\n                                            <!-- Brand -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\">\n                                                        <a href=\"##web_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"text-decoration: none; display: inline-block;\">\n                                                            <img\n                                                                src=\"##logo_url##\"\n                                                                alt=\"##web_friendly_name##\"\n                                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Trust Badges -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                width=\"100%\"\n                                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        100% Verified Profiles\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Privacy Protected\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                                    <td align=\"center\"\n                                                        style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                                        Best Matches\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Quick Action Links -->\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\" align=\"center\"\n                                                style=\"margin-bottom: 18px;\">\n                                                <tr>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##matches_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse\n                                                            Matches</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##membership_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership\n                                                            Plans</a>\n                                                    </td>\n                                                    <td\n                                                        style=\"padding: 0 4px 8px 4px;\">\n                                                        <a\n                                                            href=\"##succes_story_url##\"\n                                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success\n                                                            Stories</a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <!-- Support Box -->\n                                            <p\n                                                style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                                Need assistance? Our dedicated\n                                                relationship advisors are\n                                                available 24/7.<br>\n                                                Write to us at <a\n                                                    href=\"mailto:##contact_email##\"\n                                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a>\n                                                or call\n                                                <span\n                                                    style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                                            </p>\n\n                                            <!-- Social Media Hub -->\n                                            <table cellpadding=\"0\"\n                                                cellspacing=\"0\" border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin-bottom: 20px;\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##instagram_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//ins.png\"\n                                                                            alt=\"Instagram\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##facebook_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//fb-2.png\"\n                                                                            alt=\"Facebook\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##youtube_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//youtube.png\"\n                                                                            alt=\"Youtube\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                    <td align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"padding: 0 6px;\">\n                                                        <a\n                                                            href=\"##twitter_link##\"\n                                                            style=\"display: block; text-decoration: none;\">\n                                                            <table\n                                                                cellpadding=\"0\"\n                                                                cellspacing=\"0\"\n                                                                border=\"0\"\n                                                                width=\"36\"\n                                                                height=\"36\"\n                                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                                <tr>\n                                                                    <td\n                                                                        align=\"center\"\n                                                                        valign=\"middle\"\n                                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                                        <img\n                                                                            src=\"##template_image_url##//twitter.png\"\n                                                                            alt=\"Twitter\"\n                                                                            width=\"16\"\n                                                                            height=\"16\"\n                                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                                    </td>\n                                                                </tr>\n                                                            </table>\n                                                        </a>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                            <table role=\"presentation\"\n                                                cellpadding=\"0\" cellspacing=\"0\"\n                                                border=\"0\"\n                                                width=\"100%\"\n                                                style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                                <tr>\n                                                    <td align=\"center\"\n                                                        style=\"padding-top: 14px;\">\n                                                        <p\n                                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                                            ##footer_copywright_text##\n                                                            &#8226; <a\n                                                                href=\"##privacy_policy_url##\"\n                                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                                Policy</a>\n                                                        </p>\n                                                    </td>\n                                                </tr>\n                                            </table>\n\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n\n                    </table>\n\n                </td>\n            </tr>\n        </table>\n\n    </body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(12, 'User', 'Event Registration', 'Event Registration On ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <meta name=\"x-apple-disable-message-reformatting\">\n\n        <title>##email_subject##</title>\n\n        <style type=\"text/css\">\n        /* Email-safe reset */\n        body,\n        table,\n        td,\n        p,\n        a,\n        li,\n        blockquote {\n            -webkit-text-size-adjust: 100%;\n            -ms-text-size-adjust: 100%;\n        }\n\n        table,\n        td {\n            mso-table-lspace: 0pt;\n            mso-table-rspace: 0pt;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n            border: 0;\n            outline: none;\n            text-decoration: none;\n        }\n\n        table {\n            border-collapse: collapse;\n        }\n\n        body {\n            margin: 0 !important;\n            padding: 0 !important;\n            width: 100% !important;\n            min-width: 100% !important;\n            background-color: #FDF2F4;\n            font-family: Arial, Helvetica, sans-serif;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        .ExternalClass {\n            width: 100%;\n        }\n\n        .ExternalClass,\n        .ExternalClass p,\n        .ExternalClass span,\n        .ExternalClass font,\n        .ExternalClass td,\n        .ExternalClass div {\n            line-height: 100%;\n        }\n\n        @media screen and (max-width: 620px) {\n            .email-container {\n                width: 100% !important;\n                max-width: 100% !important;\n            }\n\n            .mobile-padding {\n                padding-left: 16px !important;\n                padding-right: 16px !important;\n            }\n\n            .header-padding {\n                padding-left: 16px !important;\n                padding-right: 16px !important;\n            }\n\n            .event-details td {\n                padding-left: 12px !important;\n                padding-right: 12px !important;\n            }\n\n            .app-column {\n                display: block !important;\n                width: 100% !important;\n                text-align: center !important;\n            }\n\n            .app-mockup {\n                width: 180px !important;\n                max-width: 180px !important;\n                margin: 20px auto 0 auto !important;\n            }\n\n            .footer-link {\n                display: block !important;\n                padding: 5px 8px !important;\n            }\n        }\n    </style>\n    </head>\n\n    <body\n        style=\"margin:0; padding:28px 10px; background-color:#FDF2F4; font-family:Arial, Helvetica, sans-serif;\">\n\n        <!-- Main Wrapper -->\n        <table\n            role=\"presentation\"\n            width=\"100%\"\n            cellpadding=\"0\"\n            cellspacing=\"0\"\n            border=\"0\"\n            align=\"center\"\n            style=\"width:100%; margin:0; padding:0; background-color:#FDF2F4;\">\n\n            <tr>\n                <td align=\"center\" valign=\"top\">\n\n                    <!-- Main Email Container -->\n                    <table\n                        role=\"presentation\"\n                        class=\"email-container\"\n                        width=\"600\"\n                        cellpadding=\"0\"\n                        cellspacing=\"0\"\n                        border=\"0\"\n                        align=\"center\"\n                        style=\"width:100%; max-width:600px; background-color:#FFFFFF; border:1px solid #FCE7EC; border-radius:28px; overflow:hidden;\">\n\n                        <!-- ================================================= -->\n                        <!-- HEADER -->\n                        <!-- ================================================= -->\n\n                        <tr>\n                            <td\n                                class=\"header-padding\"\n                                style=\"background-color:#FFFFFF; padding:18px 24px 12px 24px;\">\n\n                                <table\n                                    role=\"presentation\"\n                                    width=\"100%\"\n                                    cellpadding=\"0\"\n                                    cellspacing=\"0\"\n                                    border=\"0\">\n\n                                    <tr>\n\n                                        <!-- Logo -->\n                                        <td\n                                            align=\"left\"\n                                            valign=\"middle\"\n                                            style=\"vertical-align:middle;\">\n\n                                            <a\n                                                href=\"##web_url##\"\n                                                target=\"_blank\"\n                                                style=\"text-decoration:none;\">\n\n                                                <img\n                                                    src=\"##logo_url##\"\n                                                    alt=\"##web_friendly_name##\"\n                                                    style=\"display:block; max-height:42px; width:auto; border:0;\">\n\n                                            </a>\n\n                                        </td>\n\n                                        <!-- Contact Information -->\n                                        <td\n                                            align=\"right\"\n                                            valign=\"middle\"\n                                            style=\"vertical-align:middle;\">\n\n                                            <table\n                                                role=\"presentation\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                align=\"right\"\n                                                style=\"background-color:#FFF1F4; border:1px solid #FFE4E8; border-radius:30px;\">\n\n                                                <tr>\n\n                                                    <td\n                                                        style=\"padding:6px 14px;\">\n\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\">\n\n                                                            <tr>\n\n                                                                <!-- Phone -->\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:16px; font-weight:600; color:#DE3B68; white-space:nowrap;\">\n\n                                                                    <img\n                                                                        src=\"##template_image_url##/phone-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width:12px; height:12px; vertical-align:middle; display:inline-block; border:0;\">\n\n                                                                    &nbsp;##contact_number##\n\n                                                                </td>\n\n                                                                <!-- Separator -->\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"padding:0 8px; color:#FBCFE8; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:16px;\">\n\n                                                                    |\n\n                                                                </td>\n\n                                                                <!-- Email -->\n                                                                <td\n                                                                    valign=\"middle\"\n                                                                    style=\"font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:16px; font-weight:600; color:#475569; white-space:nowrap;\">\n\n                                                                    <img\n                                                                        src=\"##template_image_url##/mail-icon.svg\"\n                                                                        alt\n                                                                        width=\"12\"\n                                                                        height=\"12\"\n                                                                        style=\"width:12px; height:12px; vertical-align:middle; display:inline-block; border:0;\">\n\n                                                                    &nbsp;##contact_email##\n\n                                                                </td>\n\n                                                            </tr>\n\n                                                        </table>\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                        </td>\n\n                                    </tr>\n\n                                </table>\n\n                            </td>\n                        </tr>\n\n                        <!-- ================================================= -->\n                        <!-- HERO / CONTENT -->\n                        <!-- ================================================= -->\n\n                        <tr>\n                            <td\n                                class=\"mobile-padding\"\n                                style=\"padding:10px 26px 18px 26px;\">\n\n                                <!-- Hero -->\n                                <table\n                                    role=\"presentation\"\n                                    width=\"100%\"\n                                    cellpadding=\"0\"\n                                    cellspacing=\"0\"\n                                    border=\"0\">\n\n                                    <tr>\n\n                                        <td\n                                            align=\"center\"\n                                            style=\"padding-top:10px;\">\n\n                                            <!-- Avatar -->\n                                            <table\n                                                role=\"presentation\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin:0 auto 12px auto;\">\n\n                                                <tr>\n\n                                                    <td\n                                                        width=\"110\"\n                                                        height=\"110\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        bgcolor=\"#DE3B68\"\n                                                        style=\"width:110px; height:110px; background-color:#DE3B68; border-radius:55px; text-align:center; vertical-align:middle;\">\n\n                                                        <img\n                                                            src=\"##template_image_url##/event-registration.png\"\n                                                            alt=\"Event Registration\"\n                                                            width=\"65\"\n                                                            style=\"display:block; width:65px; height:auto; margin:0 auto; border:0;\">\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                            <!-- Event Badge -->\n                                            <table\n                                                role=\"presentation\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin:0 auto 10px auto;\">\n\n                                                <tr>\n\n                                                    <td\n                                                        style=\"background-color:#FFF1F4; border:1px solid #FFE4E8; border-radius:30px; padding:4px 16px; font-family:Arial, Helvetica, sans-serif; color:#DE3B68; font-size:11px; line-height:16px; font-weight:700; text-transform:uppercase; letter-spacing:1px;\">\n\n                                                        🎉 MEET &amp; GREET\n                                                        EVENT\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                            <!-- Main Heading -->\n                                            <h2\n                                                style=\"margin:0; padding:0; font-family:Arial, Helvetica, sans-serif; font-size:24px; line-height:32px; font-weight:800; color:#0F172A;\">\n\n                                                <span style=\"color:#DE3B68;\">\n                                                    Event Registration\n                                                </span>\n                                                Confirmed!\n\n                                            </h2>\n\n                                        </td>\n\n                                    </tr>\n\n                                </table>\n\n                                <!-- ================================================= -->\n                                <!-- REGISTRATION MESSAGE -->\n                                <!-- ================================================= -->\n\n                                <table\n                                    role=\"presentation\"\n                                    width=\"100%\"\n                                    cellpadding=\"0\"\n                                    cellspacing=\"0\"\n                                    border=\"0\"\n                                    style=\"margin-top:20px; margin-bottom:16px;\">\n\n                                    <tr>\n\n                                        <td\n                                            style=\"background-color:#FFF9FA; border:1px solid #FCE7EC; border-radius:20px; padding:22px 24px;\">\n\n                                            <!-- Title -->\n                                            <h5\n                                                style=\"margin:0 0 12px 0; padding:0; color:#0F172A; font-family:Arial, Helvetica, sans-serif; font-size:17px; line-height:24px; font-weight:700; text-align:center;\">\n\n                                                Your entry pass to the Pro Matri\n                                                Matchmaking Event is ready\n\n                                            </h5>\n\n                                            <!-- Greeting -->\n                                            <h6\n                                                style=\"margin:0 0 8px 0; padding:0; color:#0F172A; font-family:Arial, Helvetica, sans-serif; font-size:15px; line-height:22px; font-weight:700;\">\n\n                                                Dear\n                                                <span style=\"color:#DE3B68;\">\n                                                    ##user_name##\n                                                </span>,\n\n                                            </h6>\n\n                                            <!-- Paragraph -->\n                                            <p\n                                                style=\"margin:0 0 14px 0; padding:0; color:#475569; font-family:Arial, Helvetica, sans-serif; font-size:14px; line-height:23px; font-weight:400;\">\n\n                                                Congratulations! Your\n                                                registration for\n                                                the event has been completed\n                                                successfully on\n                                                ##web_friendly_name##.\n\n                                            </p>\n\n                                            <p\n                                                style=\"margin:0 0 14px 0; padding:0; color:#475569; font-family:Arial, Helvetica, sans-serif; font-size:14px; line-height:23px; font-weight:400;\">\n\n                                                We are excited to have you join\n                                                us.\n                                                Below are your registration\n                                                details\n                                                for your reference.\n\n                                            </p>\n\n                                            <!-- ================================================= -->\n                                            <!-- EVENT DETAILS -->\n                                            <!-- ================================================= -->\n\n                                            <table\n                                                role=\"presentation\"\n                                                class=\"event-details\"\n                                                width=\"100%\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"width:100%; background-color:#FFFFFF; border:1px solid #FCE7EC; border-radius:14px; margin:0 0 18px 0;\">\n\n                                                <!-- Event Name -->\n                                                <tr>\n\n                                                    <td\n                                                        width=\"45%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:45%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#64748B; font-family:Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:600; text-align:left;\">\n\n                                                        Event Name:\n\n                                                    </td>\n\n                                                    <td\n                                                        width=\"55%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:55%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#0F172A; font-family:Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:700; text-align:right; word-break:break-word;\">\n\n                                                        ##event_name##\n\n                                                    </td>\n\n                                                </tr>\n\n                                                <!-- Ticket Quantity -->\n                                                <tr>\n\n                                                    <td\n                                                        width=\"45%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:45%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#64748B; font-family:Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:600; text-align:left;\">\n\n                                                        Ticket Quantity:\n\n                                                    </td>\n\n                                                    <td\n                                                        width=\"55%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:55%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#DE3B68; font-family:Arial, Helvetica, sans-serif; font-size:14px; line-height:18px; font-weight:800; text-align:right; white-space:nowrap;\">\n\n                                                        ##event_ticket_qty##\n\n                                                    </td>\n\n                                                </tr>\n\n                                                <!-- Event Date -->\n                                                <tr>\n\n                                                    <td\n                                                        width=\"45%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:45%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#64748B; font-family:Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:600; text-align:left;\">\n\n                                                        Event Date:\n\n                                                    </td>\n\n                                                    <td\n                                                        width=\"55%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:55%; padding:9px 18px; border-bottom:1px solid #F1F5F9; color:#DE3B68; font-family:Arial, Helvetica, sans-serif; font-size:14px; line-height:18px; font-weight:800; text-align:right; white-space:nowrap;\">\n\n                                                        ##event_date##\n\n                                                    </td>\n\n                                                </tr>\n\n                                                <!-- Event Venue -->\n                                                <tr>\n\n                                                    <td\n                                                        width=\"45%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:45%; padding:9px 18px; color:#64748B; font-family:Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:600; text-align:left;\">\n\n                                                        Event Venue:\n\n                                                    </td>\n\n                                                    <td\n                                                        width=\"55%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:55%; padding:9px 18px; color:#DE3B68; font-family:Arial, Helvetica, sans-serif; font-size:14px; line-height:18px; font-weight:800; text-align:right; word-break:break-word;\">\n\n                                                        ##event_venue##\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                        </td>\n\n                                    </tr>\n\n                                </table>\n\n                            </td>\n                        </tr>\n\n                        <!-- ================================================= -->\n                        <!-- APP DOWNLOAD BANNER -->\n                        <!-- ================================================= -->\n\n                        <tr>\n\n                            <td\n                                class=\"mobile-padding\"\n                                align=\"center\"\n                                style=\"padding:22px 24px 0 24px;\">\n\n                                <table\n                                    role=\"presentation\"\n                                    width=\"100%\"\n                                    cellpadding=\"0\"\n                                    cellspacing=\"0\"\n                                    border=\"0\"\n                                    style=\"width:100%; background-color:#DE3B68; background-image:linear-gradient(135deg,#C2185B 0%,#DE3B68 50%,#FF537A 100%); border-radius:22px;\">\n\n                                    <tr>\n\n                                        <td\n                                            style=\"padding:24px 26px;\">\n\n                                            <table\n                                                role=\"presentation\"\n                                                width=\"100%\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\">\n\n                                                <tr>\n\n                                                    <!-- App Text -->\n                                                    <td\n                                                        class=\"app-column\"\n                                                        width=\"52%\"\n                                                        valign=\"middle\"\n                                                        style=\"width:52%; vertical-align:middle;\">\n\n                                                        <h2\n                                                            style=\"margin:0; padding:0; color:#FFFFFF; font-family:Arial, Helvetica, sans-serif; font-size:20px; line-height:26px; font-weight:800;\">\n\n                                                            Happiness is just an\n                                                            app away!\n\n                                                        </h2>\n\n                                                        <p\n                                                            style=\"margin:8px 0 0 0; padding:0; color:#FFE4E8; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:17px; font-weight:400;\">\n\n                                                            Download Our App,\n                                                            Register For Free\n                                                            &amp; Connect With\n                                                            Verified Matches\n                                                            Anywhere\n\n                                                        </p>\n\n                                                        <!-- App Store Buttons -->\n                                                        <table\n                                                            role=\"presentation\"\n                                                            cellpadding=\"0\"\n                                                            cellspacing=\"0\"\n                                                            border=\"0\"\n                                                            style=\"margin-top:14px;\">\n\n                                                            <tr>\n\n                                                                <td\n                                                                    style=\"padding-right:6px;\">\n\n                                                                    <a\n                                                                        href=\"##ios_store_url##\"\n                                                                        target=\"_blank\"\n                                                                        style=\"text-decoration:none;\">\n\n                                                                        <img\n                                                                            src=\"##template_image_url##/app-store.png\"\n                                                                            alt=\"App Store\"\n                                                                            width=\"84\"\n                                                                            style=\"display:block; width:84px; height:auto; border-radius:6px; border:0;\">\n\n                                                                    </a>\n\n                                                                </td>\n\n                                                                <td>\n\n                                                                    <a\n                                                                        href=\"##play_store_url##\"\n                                                                        target=\"_blank\"\n                                                                        style=\"text-decoration:none;\">\n\n                                                                        <img\n                                                                            src=\"##template_image_url##/play-btn.png\"\n                                                                            alt=\"Google Play\"\n                                                                            width=\"84\"\n                                                                            style=\"display:block; width:84px; height:auto; border-radius:6px; border:0;\">\n\n                                                                    </a>\n\n                                                                </td>\n\n                                                            </tr>\n\n                                                        </table>\n\n                                                    </td>\n\n                                                    <!-- App Mockup -->\n                                                    <td\n                                                        class=\"app-column\"\n                                                        width=\"48%\"\n                                                        align=\"center\"\n                                                        valign=\"middle\"\n                                                        style=\"width:48%; vertical-align:middle; text-align:center;\">\n\n                                                        <img\n                                                            class=\"app-mockup\"\n                                                            src=\"##template_image_url##/app-mokup.png\"\n                                                            alt=\"App Mockup\"\n                                                            width=\"220\"\n                                                            style=\"display:block; width:220px; max-width:100%; height:auto; margin:0 auto; border:0;\">\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                        </td>\n\n                                    </tr>\n\n                                </table>\n\n                            </td>\n\n                        </tr>\n\n                        <!-- ================================================= -->\n                        <!-- FOOTER -->\n                        <!-- ================================================= -->\n\n                        <tr>\n\n                            <td\n                                style=\"padding-top:28px;\">\n\n                                <table\n                                    role=\"presentation\"\n                                    width=\"100%\"\n                                    cellpadding=\"0\"\n                                    cellspacing=\"0\"\n                                    border=\"0\"\n                                    style=\"width:100%; background-color:#0F172A; border-radius:0 0 28px 28px; border-top:3px solid #DE3B68;\">\n\n                                    <tr>\n\n                                        <td\n                                            align=\"center\"\n                                            style=\"padding:32px 24px 24px 24px;\">\n\n                                            <!-- Footer Brand -->\n                                            <table\n                                                role=\"presentation\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin:0 auto 20px auto;\">\n\n                                                <tr>\n\n                                                    <td align=\"center\">\n\n                                                        <a\n                                                            href=\"##web_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"text-decoration:none;\">\n\n                                                            <img\n                                                                src=\"##logo_url##\"\n                                                                alt=\"##web_friendly_name##\"\n                                                                style=\"display:block; max-height:40px; width:auto; margin:0 auto; border:0;\">\n\n                                                        </a>\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                            <!-- ================================================= -->\n                                            <!-- TRUST BADGES -->\n                                            <!-- ================================================= -->\n\n                                            <table\n                                                role=\"presentation\"\n                                                width=\"100%\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                style=\"width:100%; background-color:#141E2E; border:1px solid #263244; border-radius:14px; margin-bottom:18px;\">\n\n                                                <tr>\n\n                                                    <td\n                                                        align=\"center\"\n                                                        style=\"padding:10px 8px; color:#CBD5E1; font-family:Arial, Helvetica, sans-serif; font-size:11px; line-height:16px; font-weight:500;\">\n\n                                                        100% Verified Profiles\n\n                                                    </td>\n\n                                                    <td\n                                                        align=\"center\"\n                                                        style=\"padding:10px 4px; color:#475569; font-family:Arial, Helvetica, sans-serif; font-size:10px;\">\n\n                                                        &#8226;\n\n                                                    </td>\n\n                                                    <td\n                                                        align=\"center\"\n                                                        style=\"padding:10px 8px; color:#CBD5E1; font-family:Arial, Helvetica, sans-serif; font-size:11px; line-height:16px; font-weight:500;\">\n\n                                                        Privacy Protected\n\n                                                    </td>\n\n                                                    <td\n                                                        align=\"center\"\n                                                        style=\"padding:10px 4px; color:#475569; font-family:Arial, Helvetica, sans-serif; font-size:10px;\">\n\n                                                        &#8226;\n\n                                                    </td>\n\n                                                    <td\n                                                        align=\"center\"\n                                                        style=\"padding:10px 8px; color:#CBD5E1; font-family:Arial, Helvetica, sans-serif; font-size:11px; line-height:16px; font-weight:500;\">\n\n                                                        Best Matches\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                            <!-- ================================================= -->\n                                            <!-- QUICK LINKS -->\n                                            <!-- ================================================= -->\n\n                                            <table\n                                                role=\"presentation\"\n                                                cellpadding=\"0\"\n                                                cellspacing=\"0\"\n                                                border=\"0\"\n                                                align=\"center\"\n                                                style=\"margin:0 auto 18px auto;\">\n\n                                                <tr>\n\n                                                    <td\n                                                        style=\"padding:0 4px 8px 4px;\">\n\n                                                        <a\n                                                            href=\"##matches_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"color:#E2E8F0; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:18px; font-weight:500; text-decoration:none; background-color:#1A2535; padding:5px 12px; border-radius:20px; display:inline-block;\">\n\n                                                            Browse Matches\n\n                                                        </a>\n\n                                                    </td>\n\n                                                    <td\n                                                        style=\"padding:0 4px 8px 4px;\">\n\n                                                        <a\n                                                            href=\"##membership_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"color:#E2E8F0; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:18px; font-weight:500; text-decoration:none; background-color:#1A2535; padding:5px 12px; border-radius:20px; display:inline-block;\">\n\n                                                            Membership Plans\n\n                                                        </a>\n\n                                                    </td>\n\n                                                    <td\n                                                        style=\"padding:0 4px 8px 4px;\">\n\n                                                        <a\n                                                            href=\"##succes_story_url##\"\n                                                            target=\"_blank\"\n                                                            style=\"color:#E2E8F0; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:18px; font-weight:500; text-decoration:none; background-color:#1A2535; padding:5px 12px; border-radius:20px; display:inline-block;\">\n\n                                                            Success Stories\n\n                                                        </a>\n\n                                                    </td>\n\n                                                </tr>\n\n                                            </table>\n\n                                            <!-- ================================================= -->\n                                            <!-- SUPPORT -->\n                                            <!-- ================================================= -->\n\n                                            <p\n                                                style=\"margin:0 auto 16px auto; padding:0; color:#94A3B8; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:19px; font-weight:400; max-width:460px;\">\n\n                                                Need assistance? Our dedicated\n                                                relationship advisors are\n                                                available 24/7.<br>\n\n                                                Write to us at\n\n                                                <a\n                                                    href=\"mailto:##contact_email##\"\n                                                    style=\"color:#FF537A; font-family:Arial, Helvetica, sans-serif; font-weight:600; text-decoration:none;\">\n\n                                                    ##contact_email##\n\n                                                </a>\n\n                                                or call\n\n                                                <span\n                                                    style=\"color:#F1F5F9; font-weight:600;\">\n\n                                                    ##contact_number##\n\n                                                </span>.\n\n                                            </p>\n\n                                            <!-- Social Media Hub -->\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n    style=\"margin-bottom: 20px;\">\n    <tr>\n        <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n            <a href=\"##instagram_link##\"\n                style=\"display: block; text-decoration: none;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                    height=\"36\"\n                    style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                    <tr>\n                        <td align=\"center\" valign=\"middle\"\n                            style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                            <img src=\"##template_image_url##//ins.png\"\n                                alt=\"Instagram\" width=\"16\" height=\"16\"\n                                style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                        </td>\n                    </tr>\n                </table>\n            </a>\n        </td>\n        <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n            <a href=\"##facebook_link##\"\n                style=\"display: block; text-decoration: none;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                    height=\"36\"\n                    style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                    <tr>\n                        <td align=\"center\" valign=\"middle\"\n                            style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                            <img src=\"##template_image_url##//fb-2.png\"\n                                alt=\"Facebook\" width=\"16\" height=\"16\"\n                                style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                        </td>\n                    </tr>\n                </table>\n            </a>\n        </td>\n        <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n            <a href=\"##youtube_link##\"\n                style=\"display: block; text-decoration: none;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                    height=\"36\"\n                    style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                    <tr>\n                        <td align=\"center\" valign=\"middle\"\n                            style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                            <img src=\"##template_image_url##//youtube.png\"\n                                alt=\"Youtube\" width=\"16\" height=\"16\"\n                                style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                        </td>\n                    </tr>\n                </table>\n            </a>\n        </td>\n        <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n            <a href=\"##twitter_link##\"\n                style=\"display: block; text-decoration: none;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                    height=\"36\"\n                    style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                    <tr>\n                        <td align=\"center\" valign=\"middle\"\n                            style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                            <img src=\"##template_image_url##//twitter.png\"\n                                alt=\"Twitter\" width=\"16\" height=\"16\"\n                                style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                        </td>\n                    </tr>\n                </table>\n            </a>\n        </td>\n    </tr>\n</table>\n\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n    width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n    <tr>\n        <td align=\"center\" style=\"padding-top: 14px;\">\n            <p\n                style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                ##footer_copywright_text## &#8226; <a\n                    href=\"##privacy_policy_url##\"\n                    style=\"color: #64748B; text-decoration: underline;\">Privacy\n                    Policy</a>\n            </p>\n        </td>\n    </tr>\n</table>\n\n                                        </td>\n\n                                    </tr>\n\n                                </table>\n\n                            </td>\n\n                        </tr>\n\n                    </table>\n\n                    <!-- End Main Container -->\n\n                </td>\n            </tr>\n\n        </table>\n\n    </body>\n\n</html>\n', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(13, 'User', 'Advertisement Inquiry', 'Advertisement Inquiry On ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/reff-link.png\" alt=\"Advertisement Inquiry\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                <span\n                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🎉 New Advertisement Inquiry</span>\n                            </div>\n                            <h2\n                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                <span style=\"color: #DE3B68;\">Advertisement </span> Inquiry\n                            </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n                    <h5 style=\"margin: 0 0 12px 0; color: #0F172A; font-size: 17px; font-weight: 700; text-align: center;\">\n                        Your entry pass to the Pro Matri Matchmaking Event is ready\n                    </h5>\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">Administrator</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        A new advertisement inquiry has been submitted through ##web_friendly_name##. Please review the applicant\'s information below and contact them if additional details are required.\n                    </p>\n                    \n                    <div\n                    style=\"background: #ffffff; border: 1px solid #FCE7EC; border-radius: 14px; padding: 12px 18px; margin-bottom: 18px;\">\n                        <div\n                            style=\"display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #F1F5F9;\">\n                            <span style=\"color: #64748B; font-size: 13px; font-weight: 600;\">Name:</span>\n                            <span style=\"color: #0F172A; font-size: 13px; font-weight: 700;\">##applicant_name##</span>\n                        </div>\n                        <div\n                            style=\"display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #F1F5F9;\">\n                            <span style=\"color: #64748B; font-size: 13px; font-weight: 600;\">Email:</span>\n                            <span style=\"color: #DE3B68; font-size: 14px; font-weight: 800;\">##applicant_email##</span>\n                        </div>\n                        <div style=\"display: flex; justify-content: space-between; padding: 8px 0;\">\n                            <span style=\"color: #64748B; font-size: 13px; font-weight: 600;\">Mobile:</span>\n                            <span style=\"color: #DE3B68; font-size: 14px; font-weight: 800;\">##applicant_mobile##</span>\n                        </div>\n                        <div style=\"display: flex; justify-content: space-between; padding: 8px 0;\">\n                            <span style=\"color: #64748B; font-size: 13px; font-weight: 600;\">Website / Link:</span>\n                            <span style=\"color: #DE3B68; font-size: 14px; font-weight: 800;\">##applicant_link##</span>\n                        </div>\n                        <div style=\"display: flex; justify-content: space-between; padding: 8px 0;\">\n                            <span style=\"color: #64748B; font-size: 13px; font-weight: 600;\">Contact Person:</span>\n                            <span style=\"color: #DE3B68; font-size: 14px; font-weight: 800;\">##applicant_contact_person##</span>\n                        </div>\n                    </div>\n                </div>\n            </td>\n        </tr>\n\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2026-03-16 16:13:25', NULL);
INSERT INTO `email_templates` (`id`, `email_role`, `template_name`, `email_subject`, `email_content`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(14, 'User', 'Forgot Password', 'Your profile password has been changed.', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/event-registration.png\" alt=\"Auto Match\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                <span\n                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">🔒 SECURITY & ACCESS</span>\n                            </div>\n                            <h2\n                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                <span style=\"color: #DE3B68;\">Reset </span> Your Password\n                            </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Greetings from <strong style=\"color: #0F172A;\">##web_friendly_name##</strong>. We received a request to reset\n                        your password. Click the secure button below to set a new password.\n                    </p>\n                    <div style=\"text-align: center; margin: 22px 0 10px 0;\">\n                        <a href=\"##forgot_password_link##\"\n                            style=\"display: inline-block; background: linear-gradient(135deg, #DE3B68 0%, #FF537A 100%); color: #ffffff; padding: 13px 38px; border-radius: 30px; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 700; text-decoration: none; box-shadow: 0 6px 18px rgba(222, 59, 104, 0.35);\">\n                            Reset Password\n                        </a>\n                    </div>\n                </div>\n            </td>\n        </tr>\n        <!-- App Download Banner -->\n        <tr>\n            <td align=\"center\" style=\"padding: 22px 24px 0 24px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #DE3B68; background: linear-gradient(135deg, #C2185B 0%, #DE3B68 50%, #FF537A 100%); border-radius: 22px;\">\n                    <tr>\n                        <td style=\"padding: 24px 26px;\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                                <tr>\n                                    <td width=\"52%\" valign=\"middle\">\n                                        <h2 style=\"margin: 0; font-size: 20px; color: #FFFFFF; font-family: \'Outfit\', sans-serif; font-weight: 800; line-height: 26px;\">\n                                            Happiness is just an app away!\n                                        </h2>\n                                        <p style=\"margin: 8px 0 0 0; font-size: 12px; color: #FFE4E8; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 17px;\">\n                                            Download Our App, Register For Free &amp; Connect With Verified Matches Anywhere\n                                        </p>\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top: 14px;\">\n                                            <tr>\n                                                <td style=\"padding-right: 6px;\">\n                                                    <a href=\"##ios_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/app-store.png\" alt=\"App Store\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                                <td>\n                                                    <a href=\"##play_store_url##\" style=\"display: inline-block;\">\n                                                        <img src=\"##template_image_url##/play-btn.png\" alt=\"Google Play\" width=\"84\"\n                                                            style=\"width: 84px; border-radius: 6px; display: block;\">\n                                                    </a>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                    <td width=\"48%\" align=\"center\" valign=\"middle\">\n                                        <img src=\"##template_image_url##/app-mokup.png\" alt=\"App Mockup\" width=\"220\"\n                                            style=\"max-width: 100%; width: 100%; height: auto; display: block; margin: 0 auto;\">\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL),
(15, 'Admin', 'Affiliate Registration', 'Registration Successful — Welcome to ##web_friendly_name##', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n\n    <title>##email_subject##</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style type=\"text/css\">\n        @import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\');\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 14px;\n            font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n            background-color: #FDF2F4;\n            color: #334155;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        img {\n            -ms-interpolation-mode: bicubic;\n        }\n    </style>\n</head>\n\n<body\n    style=\"margin: 0; padding: 28px 10px; background-color: #FDF2F4; font-family: \'Outfit\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\n        <tr>\n            <td align=\"center\">\n\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"600\"\n        style=\"max-width: 600px; width: 100%; background: #FFFFFF; border: 1px solid #FCE7EC; border-radius: 28px; overflow: hidden;\">\n\n        <!-- Header Section -->\n        <tr>\n            <td style=\"background: #FFFFFF; padding: 18px 24px 12px 24px;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"left\" valign=\"middle\">\n                            <a href=\"##web_url##\" target=\"_blank\"\n                                style=\"text-decoration: none; display: inline-block;\">\n                                <img alt=\"##web_friendly_name##\" src=\"##logo_url##\"\n                                    style=\"display: block; border: 0; max-height: 42px; width: auto;\" />\n                            </a>\n                        </td>\n                        <td align=\"right\" valign=\"middle\">\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                style=\"background: #FFF1F4; border: 1px solid #FFE4E8; border-radius: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 6px 14px;\" valign=\"middle\">\n                                        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                                            <tr>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #DE3B68; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/phone-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_number##\n                                                </td>\n                                                <td valign=\"middle\" style=\"color: #FBCFE8; padding: 0 8px; font-size: 12px;\">|</td>\n                                                <td valign=\"middle\" style=\"font-family: \'Outfit\', sans-serif; font-size: 12px; font-weight: 600; color: #475569; white-space: nowrap;\">\n                                                    <img src=\"##template_image_url##/mail-icon.svg\" alt=\"\" width=\"12\" height=\"12\"\n                                                        style=\"width: 12px; height: 12px; vertical-align: middle; display: inline-block;\" />\n                                                    ##contact_email##\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n        <!-- Middle Hero Section -->\n        <tr>\n            <td style=\"padding: 10px 26px 18px 26px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\n                    <tr>\n                        <td align=\"center\" style=\"padding-top: 10px;\">\n                            <!-- Avatar Circle: table-based centering, no flex, no CSS filter -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin: 0 auto 12px auto;\">\n                                <tr>\n                                    <td width=\"110\" height=\"110\" align=\"center\" valign=\"middle\" bgcolor=\"#DE3B68\"\n                                        style=\"width: 110px; height: 110px; background: #DE3B68; border-radius: 50%; text-align: center; vertical-align: middle; mso-padding-alt: 0;\">\n                                        <img src=\"##template_image_url##/registration.png\" alt=\"Registration\" width=\"65\"\n                                            style=\"width: 65px; height: auto; display: block; margin: 0 auto; border: 0;\">\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <div\n                                style=\"display: inline-block; background: #FFF1F4; border: 1px solid #FFE4E8; padding: 4px 16px; border-radius: 30px; margin-bottom: 10px;\">\n                                <span\n                                    style=\"color: #DE3B68; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px;\">✨ Thankyou For Registration</span>\n                            </div>\n                            <h2\n                                style=\"font-size: 24px; font-family: \'Outfit\', sans-serif; font-weight: 800; color: #0F172A; margin: 0; line-height: 32px; letter-spacing: -0.3px;\">\n                                <span style=\"color: #DE3B68;\">Affiliate </span> Registration\n                            </h2>\n                        </td>\n                    </tr>\n                </table>\n\n                <div\n                    style=\"margin: 20px 0 16px 0; background: #FFF9FA; border: 1px solid #FCE7EC; border-radius: 20px; padding: 22px 24px;\">\n                    <h6\n                        style=\"margin: 0 0 8px 0; font-size: 15px; font-family: \'Outfit\', sans-serif; font-weight: 700; color: #0F172A;\">\n                        Dear <span style=\"color: #DE3B68;\">##user_name##</span>,\n                    </h6>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Thank you for registering with ##web_friendly_name##. Your profile has been successfully created and is now pending approval from our admin team.\n                    </p>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Once your profile is approved, you can log in at ##web_friendly_name## to start exploring and connecting with your perfect match. We will notify you as soon as the approval process is complete.\n                    </p>\n                    <p style=\"margin: 0 0 14px 0; color: #475569; font-size: 14px; font-family: \'Outfit\', sans-serif; font-weight: 400; line-height: 23px;\">\n                        Thank you for choosing us to assist you better. If you have any questions, feel free to contact our support team.\n                    </p>\n                </div>\n            </td>\n        </tr>\n        <!-- Footer -->\n        <tr>\n            <td style=\"padding-top: 28px;\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                    style=\"background: #0F172A; border-radius: 0 0 28px 28px; border-top: 3px solid #DE3B68;\">\n                    <tr>\n                        <td align=\"center\" style=\"padding: 32px 24px 24px 24px;\">\n\n                            <!-- Brand -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <a href=\"##web_url##\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                                            <img src=\"##logo_url##\" alt=\"##web_friendly_name##\"\n                                                style=\"max-height: 40px; width: auto; display: block; margin: 0 auto; border: 0;\" />\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Trust Badges -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"\n                                style=\"background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 14px; margin-bottom: 18px;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        100% Verified Profiles\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Privacy Protected\n                                    </td>\n                                    <td align=\"center\" style=\"padding: 10px 4px; color: #475569; font-size: 10px;\">&#8226;</td>\n                                    <td align=\"center\" style=\"padding: 10px 8px; font-family: \'Outfit\', sans-serif; font-size: 11px; font-weight: 500; color: #CBD5E1;\">\n                                        Best Matches\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Quick Action Links -->\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 18px;\">\n                                <tr>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##matches_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Browse Matches</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##membership_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Membership Plans</a>\n                                    </td>\n                                    <td style=\"padding: 0 4px 8px 4px;\">\n                                        <a href=\"##succes_story_url##\"\n                                            style=\"color: #E2E8F0; font-size: 12px; font-weight: 500; text-decoration: none; background: rgba(255,255,255,0.06); padding: 5px 12px; border-radius: 20px; display: inline-block;\">Success Stories</a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <!-- Support Box -->\n                            <p style=\"margin: 0 auto 16px auto; color: #94A3B8; font-family: \'Outfit\', sans-serif; font-size: 12px; line-height: 1.6; max-width: 460px;\">\n                                Need assistance? Our dedicated relationship advisors are available 24/7.<br>\n                                Write to us at <a href=\"mailto:##contact_email##\"\n                                    style=\"color: #FF537A; text-decoration: none; font-weight: 600;\">##contact_email##</a> or call\n                                <span style=\"color: #F1F5F9; font-weight: 600;\">##contact_number##</span>.\n                            </p>\n\n                            <!-- Social Media Hub -->\n                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n                                style=\"margin-bottom: 20px;\">\n                                <tr>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##instagram_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//ins.png\"\n                                                            alt=\"Instagram\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##facebook_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//fb-2.png\"\n                                                            alt=\"Facebook\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##youtube_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//youtube.png\"\n                                                            alt=\"Youtube\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                    <td align=\"center\" valign=\"middle\" style=\"padding: 0 6px;\">\n                                        <a href=\"##twitter_link##\"\n                                            style=\"display: block; text-decoration: none;\">\n                                            <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"36\"\n                                                height=\"36\"\n                                                style=\"width: 36px; height: 36px; background: rgba(222, 59, 104, 0.22); border: 1px solid rgba(222, 59, 104, 0.45); border-radius: 50%;\">\n                                                <tr>\n                                                    <td align=\"center\" valign=\"middle\"\n                                                        style=\"text-align: center; vertical-align: middle; padding: 0;\">\n                                                        <img src=\"##template_image_url##//twitter.png\"\n                                                            alt=\"Twitter\" width=\"16\" height=\"16\"\n                                                            style=\"display: block; width: 16px; height: 16px; margin: 0 auto; border: 0;\" />\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </a>\n                                    </td>\n                                </tr>\n                            </table>\n\n                            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n                                width=\"100%\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding-top: 14px;\">\n                                        <p\n                                            style=\"margin: 0; color: #64748B; font-family: \'Outfit\', sans-serif; font-size: 11px; line-height: 1.5;\">\n                                            ##footer_copywright_text## &#8226; <a\n                                                href=\"##privacy_policy_url##\"\n                                                style=\"color: #64748B; text-decoration: underline;\">Privacy\n                                                Policy</a>\n                                        </p>\n                                    </td>\n                                </tr>\n                            </table>\n\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n\n    </table>\n\n            </td>\n        </tr>\n    </table>\n\n</body>\n\n</html>', 'APPROVED', '2025-01-16 10:59:39', '2025-01-16 10:59:52', NULL);
