INSERT INTO `personalize_home_page` (`id`, `banner_section_image`, `banner_section_heading`, `banner_section_title`, `banner_section_title2`, `banner_section_subtitle`, `feature_1_text`, `feature_2_text`, `inquiry_title`, `inquiry_subtitle`, `curation_section_banner`, `curation_section_heading`, `curation_section_title1`, `curation_section_subtitle1`, `curation_section_title2`, `curation_section_subtitle2`, `system_advantages_section_title`, `system_advantages_section_subtitle`, `advantage_1_title`, `advantage_1_subtitle`, `advantage_2_title`, `advantage_2_subtitle`, `advantage_3_title`, `advantage_3_subtitle`, `advantage_4_title`, `advantage_4_subtitle`, `assisted_service_title`, `assisted_service_subtitle`, `success_story_title`, `curation_schedule_text`, `cta_title`, `cta_subtitle`, `lang_code`, `lang_id`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '69f9c78e7a555_1777977230.webp', 'ALGORITHM-DRIVEN MATCHMAKING', 'Assisted', 'Precision.', 'Engineered for the high-performance professional. We optimize your search for a life partner using deep data analysis and dedicated human oversight.', '100% ID Verified', 'Discretion Guaranteed', 'Interested in Assisted Service?', 'Leave your details and our expert will call you back.', '69f9c31602ced_1777976086.webp', 'Data-Driven<br>Human Curation.', 'Relationship Manager Logic', 'Not just a consultant, but a strategic partner who filters through thousands of data points to present only verified, high-compatibility profiles.', 'Efficiency Optimization', 'We handle the outreach, initial vetting, and scheduling. You only show up for the high-value interaction.', 'System Advantages', 'How we maximize your success rate.', 'Private Profile Access', 'Gain entry to a curated pool of verified members whose profiles are intentionally kept off public directories to ensure complete privacy.', 'Discreet Discovery', 'Explore potential matches through a confidential process where identities and personal details are revealed only at the appropriate stage.', 'Verified High-Caliber Members', 'Connect with accomplished professionals who prefer a controlled, secure environment for meaningful introductions.', 'Secure Matchmaking Process', 'Every interaction is handled with strict confidentiality, ensuring your search remains personal, protected, and respectful.', 'Get Assisted Service', 'Transparent pricing for premium execution.', 'Assisted Service Member Testimonials', 'Schedule Executive Briefing', 'Want to know more about Assisted Service?', 'Schedule Executive Briefing', 'en', NULL, 'APPROVED', '2025-01-24 12:29:10', '2026-05-05 16:11:31', NULL);
