(11, 'faq', 'APPROVED', 'Faq', NULL, 'Matrimony FAQs – Common Questions Answered', 'Find answers to common questions about registration, profile search, membership plans and safety on Pro Matrimony matrimony.', 'matrimony faq, matrimonial questions, help', NULL, 'noindex, nofollow', 'Matrimony FAQs – Common Questions Answered', 'Find answers to common questions about registration, profile search, membership plans and safety on Pro Matrimony matrimony.', NULL, 'website', NULL, NULL, NULL, NULL, '{\"@context\":\"https:\\/\\/schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Is registration free on Pro Matrimony?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes, you can register and create your matrimonial profile for free.\"}},{\"@type\":\"Question\",\"name\":\"How can I search for bride or groom profiles?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"You can use quick search, advanced search, keyword search or ID search options.\"}},{\"@type\":\"Question\",\"name\":\"Are profiles verified?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes, we manually and automatically verify profiles to ensure authenticity.\"}},{\"@type\":\"Question\",\"name\":\"What are membership benefits?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Membership allows you to chat, view contact details and connect directly with matches.\"}}]}', 0.8, 'weekly', NULL, 'en', NULL, NULL, NULL, NULL, NULL),
